async function center(q){for(const [axis,t]of[['x',q.x+.5],['z',q.z+.5]]){for(let k=0;k<45&&Math.abs(bot.entity.position[axis]-t)>.04;k++){await bot.lookAt(bot.entity.position.offset(axis==='x'?Math.sign(t-bot.entity.position.x)*5:0,1.4,axis==='z'?Math.sign(t-bot.entity.position.z)*5:0),true);bot.setControlState('sneak',true);bot.setControlState('forward',true);await tick(1);bot.clearControlStates();await tick(2)}if(Math.abs(bot.entity.position[axis]-t)>.12)throw Error('CENTER_ACTUAL')}}
