async function emerge(){const s=global.P1Overland;if(!s)return;if(!s.feet.equals(bot.entity.position.floored())||!shell(s.feet))throw Error('EMERGE_START');const coldCount=()=>bot.inventory.items().filter(i=>coldNames.includes(i.name)).reduce((a,i)=>a+i.count,0);if(coldCount()<2){let got=false;for(const d of dirs){const q=s.feet.plus(d).offset(0,1,0),b=bot.blockAt(q);if(!['dirt','grass_block'].includes(b.name))continue;const faces=[...dirs,new Vec3(0,1,0),new Vec3(0,-1,0)];if(!faces.every(v=>q.plus(v).equals(s.feet.offset(0,1,0))||full(bot.blockAt(q.plus(v)))))continue;await cut(b);for(let k=0;k<35&&coldCount()<2;k++)await tick(1);if(coldCount()>=2){got=true;console.log('EXIT_ONE_DIRT_ACTUAL',coldCount());break}}if(!got)throw Error('NEED_ONE_COLD_EXIT_RETAINED')}await cut(bot.blockAt(s.roof));for(let h=1;h<=2;h++){const b=bot.blockAt(s.roof.offset(0,h,0));if(b&&["spruce_log","spruce_leaves","oak_log","oak_leaves"].includes(b.name))await cut(b);else if(!air(b))throw Error('EMERGE_CEILING_'+b?.name);}for(let k=0;k<35&&coldCount()<3;k++)await tick(1);for(let y=s.feet.y;y<=s.roof.y;y++){await center(new Vec3(s.feet.x,y,s.feet.z));if(!stock())throw Error('UP_STOCK');await bot.equip(stock(),'hand');bot.setControlState('jump',true);for(let k=0;k<15&&bot.entity.position.y<y+.95;k++)await tick(1);try{await bot._placeBlockWithOptions(bot.blockAt(new Vec3(s.feet.x,y-1,s.feet.z)),new Vec3(0,1,0),{forceLook:true})}finally{bot.setControlState('jump',false)}await tick(10);if(!full(bot.blockAt(new Vec3(s.feet.x,y,s.feet.z)))||Math.abs(bot.entity.position.y-y-1)>.15)throw Error('UP_POST')}global.P1Overland=null;await arm();console.log('EMERGED_ACTUAL',bot.entity.position)}
